// The French of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/fr/index.ts).
export const whatsNew: Record<string, string> = {
  "What's new": 'Nouveautés',
  'What each version changed': 'Ce que chaque version a changé',
  'What each version of Erevos changed, the newest first.': 'Ce que chaque version d’Erevos a changé, la plus récente en premier.',
  'Not out yet': 'Pas encore sortie',
  'This version': 'Cette version',
  'For you': 'Pour toi',
  'Under the hood': 'Sous le capot',
  // Not out yet.
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Les liens s'ouvrent sous Sailfish OS** : **Se connecter avec LPHL**, une page de don ou un lien dans une discussion n'ouvraient rien. Désormais Sailfish OS les ouvre : une page web dans le navigateur, un numéro dans le téléphone ou les messages, une adresse dans le courriel.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, et les photos et fichiers des discussions XMPP et Nostr, sous Sailfish OS** : Erevos n'y joignait pas leurs serveurs en HTTPS, donc Matrix ne pouvait pas se connecter, les photos et fichiers n'arrivaient ni ne partaient, et les liens n'avaient pas d'aperçu. Désormais ils fonctionnent comme sur un ordinateur.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Un appel téléphonique affiche son écran** : avec Erevos comme app Téléphone, un appel entrant pouvait sonner écran noir, sans qu’on puisse répondre, quand les notifications plein écran d’Android pour Erevos, les notifications d’Erevos ou ses notifications d’appels entrants étaient désactivées. Désormais, l’écran d’appel s’affiche tout seul, même sur l’écran de verrouillage, et allume l’écran. Un appel que « Ne pas déranger » retient arrive toujours en silence, écran éteint. Voir [Téléphone](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**La calculatrice affiche un long résultat depuis le début** : en portrait, un résultat avec beaucoup de décimales cachait ses premiers chiffres, visibles seulement téléphone tourné. Désormais, un long nombre rapetisse pour tenir, ses premiers chiffres toujours visibles.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Choisir le destinataire d'un nouveau SMS parmi les contacts** : **Nouveau SMS** a un bouton **Contacts** qui ouvre tes contacts avec une recherche, et en tapant un nom ou un numéro, les contacts qui correspondent sont proposés. Un contact avec plusieurs numéros montre une ligne pour chacun, et pour un MMS de groupe chaque contact choisi s'ajoute. Avec seulement les SMS ouverts, seuls les contacts du téléphone s'affichent. Voir [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Plus pour un numéro dans le Téléphone** : sur le clavier, **⋯** à côté d’un numéro tapé propose **Ajouter aux contacts**, **Ajouter à un contact existant**, **Envoyer un SMS** et **Copier le numéro**. **Récents** et **Favoris** proposent **Copier le numéro** et **Ouvrir le contact** ; **Favoris** aussi **Envoyer un SMS**, et **Récents** ajoute un numéro inconnu à un contact existant. Avec Erevos verrouillé, le Téléphone ne fait toujours qu’appeler. Voir [Téléphone](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Une brève vibration au toucher** : les touches du clavier, **Appeler**, **Raccrocher**, Envoyer, la touche Entrée du clavier, les interrupteurs et les menus qui s’ouvrent font vibrer brièvement. **Réglages** → **Apparence** → **Vibrer au toucher** l’éteint. Voir [Apparence](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Un nombre sur chaque icône, sur Huawei et Honor** : leurs lanceurs montrent maintenant un nombre sur chaque icône d’Erevos à part, avec **Nombre sur l’icône** activé : sur celle d’Erevos les messages, sur celle des SMS les SMS non lus, sur celle du Téléphone les appels manqués, sur celle des Contacts un anniversaire du jour. La plupart des autres lanceurs, comme ceux des Pixel et de GrapheneOS, celui de Samsung et Kvaesitso, donnent le point ou le nombre d’une notification à toutes les icônes d’une appli à l’identique, et là Erevos n’y peut rien changer. Voir [Apparence](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Choisis les parties d’Erevos que tu utilises** : les discussions propres à Erevos, le Téléphone, les SMS et les discussions avec des apps Nostr, Matrix et XMPP sont désormais des modules, n’importe lesquels peuvent être activés, ceux d’Erevos aussi, au moins un. Un module désactivé ne démarre pas et n’apparaît nulle part, et les icônes du Téléphone et des SMS quittent les apps du téléphone : Erevos est plus léger, s’ouvre plus vite et consomme moins de batterie. Rien n’en est supprimé : tout est de retour quand il est réactivé. Le tout premier démarrage d’Erevos le configure comme le fait un installateur, sa langue, les modules et ce qu’Android doit autoriser pour eux ; un module activé plus tard redemande ses autorisations. Après cette mise à jour, chaque module reste activé jusqu’à ce que tu les changes dans **Réglages** → **Général** → **Modules**. Voir [Modules](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publications publiques dans l’onglet Nostr** : sur l’écran d’accueil, l’onglet Nostr montre d’abord **Publications**, les publications publiques des personnes que suit ta clé Nostr et ce qu’elles ont repartagé, les plus récentes d’abord, comme dans Amethyst ou une chaîne Telegram, avec **Discussions** à un appui. Les plus anciennes arrivent quand tu fais défiler jusqu’au bout, les plus récentes quand tu tires la liste vers le bas ; touche qui a écrit une publication pour ses publications ou pour lui écrire. En lecture seule, cherché par Tor comme le dit l’espace et pas gardé, et aucune image ni aucun lien n’est ouvert. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Les discussions masquées sur tes appareils associés** : chaque emplacement de discussions masquées s’associe désormais à part, depuis l’intérieur, au même emplacement sur un ordinateur ou dans un navigateur, avec **Appareils associés** sous sa liste. Ses discussions, messages, groupes, appels, sa Discussion avec moi-même et ses propres comptes Matrix, XMPP et Nostr y vont, et ses contacts lui écrivent là directement. Rien de cela ne se voit dans l’espace ni sur les appareils associés de l’espace. L’association fonctionne tant que l’emplacement est ouvert, et fermé aussi avec **Recevoir une fois fermées** activé. Voir [Appareils associés](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Déplacer une discussion dans un autre espace** : dans les **Détails** d’une discussion, **Déplacer dans un autre espace** l’emmène, avec ses messages, son nom, son image, son apparence et les discussions importées, dans l’espace dont tu tapes le mot de passe, comme un déplacement dans les discussions masquées : le numéro de sécurité reste le même, et le téléphone du contact est aussitôt informé qu’il doit y écrire. Cet espace reste fermé, et la ligne s’affiche dans chaque espace. Une discussion ne prend jamais la place d’une autre que cet espace, ou des discussions masquées, ont déjà avec la même personne. Voir [Second mot de passe](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos ne s’arrête plus quand seuls les SMS ou les contacts sont ouverts** : de là, le chat d’un contact, un SMS, une autre icône ou un écran qui redemande le mot de passe pouvaient faire dire à Erevos qu’il n’a pas pu s’ouvrir (Maximum call stack size exceeded). Désormais le mot de passe ouvre tout Erevos, puis cet écran. Et quand Erevos ne peut pas s’ouvrir, **Réessayer** le relance. Voir [Verrou par mot de passe](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Chaque icône ouvre ce qu’elle désigne** : après l’ouverture d’Erevos par l’icône SMS ou depuis les applis récentes, une autre icône, le widget ou une notification pouvaient parfois afficher les SMS à la place. Désormais chacun ouvre ce qu’il désigne. Quand seuls les SMS ou les contacts sont ouverts, une autre icône demande le mot de passe comme quand Erevos est verrouillé, puis ouvre sa propre partie : l’icône Contacts seulement les contacts, l’icône d’Erevos elle-même tout Erevos. Et Retour sur le premier écran d’Erevos le met désormais en arrière-plan, comme Accueil, quelle que soit la façon dont il a été ouvert. Voir [Verrou par mot de passe](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Seulement les contacts** : quand Erevos est verrouillé, l’icône Contacts, le bouton Contacts du widget et la notification d’un anniversaire demandent le mot de passe, puis n’ouvrent que les contacts. Une discussion, un SMS, les Réglages et le cadenas orange **Tout déverrouiller** le redemandent, puis ouvrent tout Erevos. Voir [Verrou par mot de passe](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Anciens messages privés dans les discussions Nostr** : Erevos lit aussi les messages privés envoyés à l’ancienne manière (NIP-04), que Damus, Primal et beaucoup d’applis envoient et gardent encore : passés et nouveaux, dans les mêmes discussions. Les relais voient qui a écrit un tel message à qui ; Erevos lui-même continue de n’envoyer qu’à la manière de NIP-17. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publications publiques dans les discussions Nostr** : dans une discussion avec une personne, **Publications publiques** montre ce que la personne publie pour tous, les plus récentes d’abord, en lecture seule. C’est cherché par Tor comme le dit l’espace et rien n’en est gardé, et aucune image ni aucun lien n’est ouvert. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licence** : Réglages → Général → Licence dit sous quelle licence Erevos est un logiciel libre, AGPL-3.0-or-later, ses trois conditions supplémentaires, qu’il vient sans aucune garantie, et qui l’a fait. Voir [Licence](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contact** : Réglages → Général → Contact ajoute l’auteur d’Erevos comme contact, pour lui écrire dans Erevos même, avec chiffrement de bout en bout, sans numéro de téléphone ni e-mail. Voir [Ce qu’est Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Une nouvelle série d’autocollants, Angry Eyes** : 24 visages de grands yeux jaunes sur un disque noir, dessinés par l’auteur d’Erevos, chacun avec les mouvements qu’il lui a donnés.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**La calculatrice s’ouvre de nouveau** : dans la 4.0.0-rc.6, elle se fermait dès que tu la touchais.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr sont cherchées sur davantage de relais** : **Afficher les personnes que tu suis** interroge aussi des relais qui rassemblent des listes de personnes suivies et davantage des relais où écrit ta clé, et les attend plus longtemps ; quand il ne trouve personne, il dit pourquoi et comment chaque relais a répondu. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Mot de passe de panique** : avec le verrou par mot de passe activé, **Définir le mot de passe de panique** dans « Bouton de panique » définit un mot de passe à part qui, saisi sur l’écran de verrouillage, efface Erevos comme **Tout effacer maintenant**, tandis que l’écran affiche **Mot de passe incorrect**. Rien ne montre s’il y en a un de défini. Voir [Bouton de panique](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calculatrice à la place d’Erevos** : sur Android, dans « Icônes du lanceur », une calculatrice qui fonctionne peut prendre la place de l’icône d’Erevos ; ton code, puis **=**, ouvre Erevos, qui demande son mot de passe comme toujours. Voir [Apparence](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Discussion avec moi-même aussi sur tes appareils associés** : les notes, photos, fichiers, messages vocaux et rappels écrits sur un appareil vont aux autres, de même qu’un rappel changé ou vu et une note supprimée. Ceux d’avant partent une fois, dans les deux sens. Voir [Appareils associés](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Démarrer à l’allumage du téléphone** : sur Android, dans « En arrière-plan », Erevos peut démarrer tout seul après l’allumage du téléphone, si bien que les espaces réglés pour dire qu’un message est arrivé pendant qu’ils sont fermés disent déjà « New message », jamais quel espace ni quoi. Désactivé sauf si tu le choisis. Voir [Discuter par un relais](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Avancer l’horloge ne met plus fin à l’attente après des mots de passe incorrects** : elle suit le temps propre du téléphone depuis son démarrage, que personne ne peut régler ; après un redémarrage, elle repart de son début. Voir [Verrou par mot de passe](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr, trouvées là où ton autre appli les garde** : avec une clé venue d’une autre appli Nostr, **Afficher les personnes que tu suis** cherche aussi sur les relais où écrit ta clé, et le dit quand aucun relais n’a répondu. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ton nom Nostr garde le reste de ton profil** : enregistrer **Ton nom** ne change que le nom dans ton profil ; une photo ou des mots qu’une autre appli de ta clé y a mis restent. Avant, ils pouvaient être effacés. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Les écrans redescendent quand aucun clavier n’est ouvert, dans tous les cas** : la liste et les boutons de l’écran d’accueil, ou une discussion, pouvaient encore rester en haut comme si un clavier était ouvert, après son départ. Maintenant Erevos demande à Android lui-même si un clavier est affiché, et sans clavier ils redescendent en moins d’une seconde.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nouvelle discussion ouvre plus vite les discussions masquées** : maintiens **Nouvelle discussion** un instant, plus une seconde entière, et le champ pour un code PIN de discussions masquées s’ouvre ; sur Android le téléphone vibre une fois à l’ouverture. Voir [Discussions masquées](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr** : dans les Discussions Nostr, sous Nouvelle discussion, **Afficher les personnes que tu suis** liste les personnes que suit ta clé Nostr, avec leurs noms ; touches-en une pour lui écrire. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Qui fait Erevos, et sa licence** : À propos d’Erevos dit désormais qui le fait, et chaque fichier du code source dit à qui il appartient et sous quelle licence ; la licence AGPL-3.0 a trois conditions ajoutées (garder le nom de l’auteur, marquer une version modifiée comme modifiée, lui donner un autre nom). Vois [Ce qu’est Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Des nombres sur les puces de l’écran d’accueil** : chaque puce au-dessus des discussions (Tous, SMS, Erevos, Matrix, XMPP, Nostr) montre combien de messages n’y sont pas lus, en un petit nombre après son nom ; les discussions et groupes en sourdine ne comptent pas. Voir [Premiers pas](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Photo en plein écran dans les discussions Matrix, XMPP et Nostr** : touche une photo affichée dans une discussion Matrix, XMPP ou Nostr pour la voir sur tout l’écran, avec le zoom, la rotation avec le téléphone et Enregistrer, comme dans la discussion avec un contact. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Qui a reçu et qui a lu tes messages dans les groupes** : dans un groupe qui n’est pas public, tes messages montrent ✓, puis ✓✓ quand ils sont arrivés sur le téléphone de chaque membre, et ✓✓✓ quand tous les ont lus. Maintiens-en un et choisis **Qui l’a lu** pour voir qui l’a lu et quand, sur le téléphone de qui il est arrivé et quand, et qui n’a encore fait ni l’un ni l’autre. Un membre dont l’Erevos est plus ancien ne dit rien. Un ordinateur associé montre les mêmes marques. Voir [Discuter par un relais](#relay) et [Discussions de groupe](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Qui a lu tes messages dans Matrix** : tes messages dans une discussion Matrix montrent ✓ quand le serveur Matrix les a pris et ✓✓✓ quand tous les autres membres les ont lus, comme leurs applis Matrix le disent à leurs serveurs ; **Qui l’a lu**, sur un message maintenu, liste qui l’a lu et quand, et qui ne l’a pas lu. Matrix n’a pas de marque pour un message arrivé sur un téléphone, donc il n’y a pas de ✓✓. Voir [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Des messages de groupe discrets pour les marques** : le message de groupe qui dit qu’un message est arrivé ou a été lu ne va qu’aux expéditeurs concernés, et groupé ; après 300 de ces messages envoyés à certains membres seulement, le suivant va à tous, pour qu’aucun membre ne prenne de retard dans les clés MLS du téléphone (elles acceptent un saut de 1000 au plus). Les groupes lâchés quand leur espace se ferme n’envoient plus rien. Voir [Discussions de groupe](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Gras, italique, code et mots cachés** : dans les discussions et les groupes, les mots entre * passent en gras, entre _ en italique, entre ~ barrés, entre ` en code, et entre || cachés derrière une barre grise jusqu’à ce que vous touchiez. Voir [Discuter par un relais](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Photo cachée** : sous + dans une discussion ou un groupe, une photo qui apparaît floue jusqu’à ce que vous la touchiez. Voir [Discuter par un relais](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Message de sécurité** : sous + dans une discussion, des mots pour un contact que le relais envoie tout seul si vous n’ouvrez pas Erevos pendant 6 heures à une semaine ; chaque fois que vous l’ouvrez, ils sont repoussés. Voir [Discuter par un relais](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Nommer un membre dans un groupe avec @** : tapez @ et choisissez un membre ; il est averti du message même s’il a mis le groupe en sourdine. Voir [Discussions de groupe](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Répondre, modifier, réagir et supprimer dans les discussions XMPP** : un appui long sur un message d’une discussion ou d’un groupe XMPP permet d’y répondre, de changer tes mots, de le supprimer pour tout le monde ou d’y réagir avec un emoji, comme le font Conversations, Dino, Gajim, Monal et Kaidan ; et **écrit…** s’affiche pendant que l’autre personne écrit. Voir [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Vois qui écrit dans une discussion Matrix** : **écrit…** s’affiche sous une discussion Matrix pendant que quelqu’un y écrit, comme le dit le serveur Matrix. Les autres ne le voient de toi que si tu actives **Dire quand j’écris** sur l’écran Matrix ou XMPP : désactivé au départ, car cela passe par le serveur sans chiffrement. Voir [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Bloquer quelqu’un sur XMPP** : Bloquer, en bas d’une discussion XMPP, écarte les messages, appels et demandes de cette personne de toutes les applis de ton compte XMPP ; Débloquer la laisse passer à nouveau. Voir [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Messages vocaux dans les discussions XMPP** : appuie longuement sur le micro sous la zone de message d’une discussion XMPP pour enregistrer, et relâche pour envoyer ; il part chiffré comme la discussion, comme Conversations l’envoie. Voir [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Des groupes Matrix depuis Erevos** : Nouveau groupe, sur l’écran Matrix, crée un groupe chiffré avec un nom et les personnes que tu invites ; Rejoindre un groupe en rejoint un par son adresse ; Inviter, dans un groupe, y fait venir quelqu’un d’autre ; taper @ dans un groupe nomme un membre, qui est prévenu. Voir [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Le bouton de panique sur un ordinateur et sur Sailfish OS** : Réglages → Confidentialité et sécurité → Bouton de panique efface désormais Erevos là aussi, avec ses sauvegardes automatiques si vous le choisissez ; sur un ordinateur, il redémarre ensuite comme neuf. Voir [Bouton de panique](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Chaque discussion s’ouvre sur son dernier message** : les discussions avec des contacts, les groupes et les SMS, et les discussions Matrix, XMPP et Nostr s’ouvrent toutes sur le dernier message avec la barre de message en dessous, et ont des flèches rondes vers le début, vers là où tu en étais (le premier message qui était nouveau à l’ouverture) et vers la fin. Voir [Premiers pas](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Le bouton de panique dit quand il a refusé** : quand votre app de panique a demandé d’effacer Erevos alors que l’interrupteur était coupé, ou signée d’une autre clé, l’écran du bouton de panique le dit désormais, avec l’heure. Une app qui passe à une nouvelle clé comme Android le permet reste de confiance ; sinon vous pouvez lui refaire confiance telle qu’elle est maintenant. Voir [Bouton de panique](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Les puces de l’écran d’accueil restent sur une seule ligne** : avec en plus une puce Nostr, Matrix ou XMPP, **Noms** passait sur une ligne à part et les puces bougeaient. Maintenant elles restent sur une seule ligne qui glisse sur le côté, et celle que tu as choisie reste toujours en vue.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Les écrans redescendent quand le clavier est parti** : en revenant d’une autre appli dont le clavier était ouvert, les boutons de l’écran d’accueil (ou le champ d’une discussion) pouvaient rester en haut, là où était le clavier, jusqu’à ce qu’un clavier s'ouvre de nouveau. Maintenant ils redescendent en moins d’une seconde.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Vois ce que tu tapes dans un mot de passe ou un PIN** : chaque champ pour un mot de passe, un PIN ou un jeton a un œil au bout : touche-le pour voir ce que tu tapes, et encore pour le masquer. La fois suivante, il est de nouveau masqué. Voir [Verrou par mot de passe](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Une discussion lue pendant qu’elle s’ouvre reste lue** : les messages lus alors que leur discussion s’ouvrait encore, le temps qu’Erevos finisse de regarder sur le relais, apparaissaient comme non lus sur l’écran d’accueil dès que tu revenais. Maintenant, ils sont marqués comme lus dès qu’ils s’affichent.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Lien pour un site web** : dans Nouvelle discussion → Ton lien de contact, un lien à mettre sur une page web, comme ta page de contact. Il ouvre une page qui propose Erevos à qui ne l’a pas encore, puis t’ajoute ; ce qu’on envoie arrive comme demande de message. Voir [Discuter par un relais](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Un téléchargement de mise à jour qui se bloque est réessayé** : quand la connexion n’apporte plus rien pendant un moment, Erevos reprend le téléchargement de lui-même, trois fois en tout, puis le dit avec ses propres mots. Voir [Mises à jour](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Les morceaux de photos par Nostr restent avec leurs discussions** : tant qu’une photo qui arrive par Nostr attend le reste de ses morceaux, ceux-ci sont désormais gardés chiffrés avec l’espace ou les discussions masquées pour lesquels ils sont venus, et non plus à part, où l’on pouvait les compter : rien hors du mot de passe de discussions masquées ne dit qu’une photo est en route vers elles. Les morceaux gardés avant vont aux premières discussions dont ils sont la photo, ou partent après quatre jours. Voir [Par Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS chiffrés quand rien d’autre ne marche, si tu le choisis**: sur Android, quand le relais, Nostr, les téléphones à proximité et LoRa échouent tous, un texte à un contact Erevos dont le numéro est lié peut partir par SMS, chiffré de bout en bout et caché de son app SMS. Désactivé jusqu’à ce que tu l’actives, pour tous ces contacts dans Réglages → Téléphone et SMS → SMS, ou pour un seul dans les Détails d’une discussion. Ça coûte des SMS (3 pour un texte court, jusqu’à 10 pour un plus long), et l’opérateur voit qui a écrit à qui, et quand. Les deux téléphones ont besoin d’Erevos comme app SMS. Voir [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Répondre à un appel masqué avec Répondre** : sur l’écran « Appel entrant » sans nom qu’apporte un appel vers tes discussions masquées, **Répondre** demande maintenant le code PIN, comme le petit signe, et le bon code PIN répond à l’appel ; avant, il ne pouvait pas connecter, et seul le petit signe le pouvait. Voir [Discussions masquées](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Les SMS de spam arrivent en silence** : sur Android, un SMS que les mots propres du filtre anti-spam attrapent, un lien avec des mots qui cherchent à tromper d’un numéro qui n’est pas un contact et auquel tu n’as jamais répondu, va toujours dans Spam mais n’affiche plus de notification ni ne sonne. Le spam par tes propres mots et règles en affiche toujours une, car ils restent chiffrés dans l’espace ; avec le Filtre anti-spam désactivé, chaque SMS en affiche une. Voir [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Les nouveautés en deux parties** : chaque version dit d’abord ce qui change pour toi, puis ce qui a changé sous le capot : corrections, vitesse, batterie et sécurité à l’intérieur. Voir [Mises à jour](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Les SMS d’un contact ne restent plus comptés comme nouveaux** : ouvrir son chat les lit tous, les plus anciens aussi, pas seulement ceux qui s’affichent.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Un message n’attend plus quand Tor n’atteint pas le relais** : avec Tor pour les messages, il part aussitôt en direct, comme le disent les réglages de Tor. Voir [Par Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Les avis en arrière-plan ne s’arrêtent plus après un changement de réseau** : quand la connexion d’une attente au relais mourait en route (du Wi-Fi aux données mobiles, redémarrage du relais), Erevos prenait le relais pour un ancien, qui ne sait pas attendre, pour toute la session : les messages des contacts arrivaient jusqu’à dix minutes en retard, et les discussions masquées, les espaces fermés et les sonneries masquées ne disaient rien jusqu’au redémarrage d’Erevos. Voir [Discuter par un relais](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Un appel raccroché aussitôt ne sonne plus** : quand le raccrochage arrivait dans le même regard que l’appel, le téléphone sonnait 45 secondes pour un appel où personne n’était ; de même pour un appel de groupe que celui qui l’a lancé a quitté aussitôt. Voir [Discuter par un relais](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Un appel masqué sonne une fois** : un lieu avec Recevoir une fois fermées et une file de sonnerie sonnait deux fois pour un appel, et un appel pris pendant que les discussions masquées étaient ouvertes sonnait de nouveau à leur fermeture. Voir [Discussions masquées](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Le lien de contact d’un membre ne dit plus Nouveau message** : la réponse à une demande depuis un groupe ajoute seulement le contact, sans avis. Voir [Discussions de groupe](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**L’avis d’anniversaire et l’appel entrant du téléphone ne se remplacent plus** : ils avaient le même numéro d’avis. Voir [Contacts](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Un espace fermé signale aussi les messages de ses contacts** : comme chaque contact écrit dans sa propre file d’attente, un espace qui signale qu’un message est arrivé pendant qu’un autre est ouvert ne signalait que les messages de groupes et les premiers messages de nouveaux contacts. Il interroge maintenant aussi les files d’attente de ses contacts, jusqu’à 64. Voir [Discuter par un relais](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**Le guide d’utilisation est dans toutes les langues de l’app** : il s’affiche dans celle que tu as choisie et nomme les boutons comme l’app les affiche. Voir [Langue](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Position trouve où tu es, à l’intérieur aussi** : le téléphone cherche par satellite et par son réseau à la fois, une feuille dit qu’il cherche, et si rien n’est trouvé elle dit pourquoi, avec Réessayer. Voir [Discuter par un relais](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**L’icône de l’app web compte les non-lus** : sur un iPhone, avec les notifications activées pour l’espace, l’icône d’Erevos sur l’écran d’accueil montre combien de messages ne sont pas lus, jamais ceux d’une discussion masquée, sauf si tu l’enlèves dans Réglages → Notifications → Nombre sur l’icône. Voir [Sur un iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Des notifications pour chaque discussion** : sur Android, mets une discussion ou un groupe en sourdine pendant 8 heures, une semaine ou toujours, et donne à ses messages et à ses appels un son à eux, ou aucun. Voir [Discuter par un relais](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Une discussion verrouillée par son propre code PIN reste verrouillée** : quand l’Erevos du contact commençait une nouvelle conversation, comme il le fait environ une fois par mois, la discussion perdait son code PIN, et un groupe public rejoint à nouveau perdait le sien. Voir [Discussions masquées](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**L’icône d’Erevos garde le nombre de messages non lus, sur Android** : quand tu quittes Erevos avec des messages non lus, une notification sans son garde combien jusqu’à ce que tu les lises, et le launcher l’affiche sur l’icône, comme nombre ou point. Réglages → Notifications → Nombre sur l’icône le désactive. Voir [Discuter par un relais](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    '**Les notifications de l’app web, plus fiables** : plus de « Nouveau message » par-dessus Erevos quand il est ouvert, et un push retenu pendant que le téléphone était hors ligne ne compte plus les messages que tu as déjà lus (les deux avec ton relais à jour), chaque avis sonne dans Chrome, Firefox et Edge, elles reviennent d’elles-mêmes quand le navigateur change son adresse push, et « Notifications quand l’app est fermée » dit quand le navigateur les bloque ou que ton relais n’a pas encore été prévenu qu’elles sont désactivées. Voir [Sur un iPhone](#iphone).',
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Les appels sonnent dans l’app web, sur l’ordinateur et sur Sailfish OS** : un appel qui arrive pendant qu’Erevos est ouvert sonne désormais, là où seul son écran s’affichait, et vibre là où le téléphone le peut. Sur un iPhone, il sonne une fois que tu as touché Erevos, et pas en mode silencieux. Voir [Sur un iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos sur un ordinateur continue de tourner fenêtre fermée** : dans la zone de notification (sur un Mac, dans le Dock), il continue de recevoir, un appel sonne et fait revenir la fenêtre, et une notification dit combien de messages ne sont pas lus, jamais de qui ni quoi. À désactiver dans Réglages → Notifications → En arrière-plan. Voir [Sur un ordinateur](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos sur Sailfish OS signale messages et appels pendant qu’il est fermé** : tant qu’il n’est pas à l’écran ou est fermé, un petit assistant attend sur le relais pour l’espace ouvert, une notification dit combien de messages sont arrivés, jamais de qui ni quoi, et un appel sonne avec la sonnerie du téléphone. Voir [Sur Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    '**Les push du relais vers l’app web, plus robustes** : un push que le service push n’a pas pu accepter à ce moment-là est renvoyé, un appel passe avant les messages qui attendent leur tour, et la personne qui gère le relais peut autoriser un autre service push. Ton relais doit être mis à jour pour cela.',
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Autorisations vérifie chaque notification qu’Erevos utilise** : sur Android, la notification des messages sans son ou avec le son propre d’une discussion, et celle des rappels, quand elles sont désactivées, s’affichent maintenant là, avec un bouton pour chacune. Voir [Discuter par un relais](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Les discussions masquées disent ce dont leurs interrupteurs ont besoin** : Prévenir quand un message arrive et Faire sonner les appels quand elles sont fermées le disent quand Réglages → Notifications → En arrière-plan ne les laisse rien faire. Voir [Discussions masquées](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Des mots plus justes sur les notifications** : les Réglages et le guide donnent les mots mêmes des notifications et disent ce dont chacune a besoin. Voir [Discuter par un relais](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Les appels sonnent comme il faut** : avec Ne pas déranger seulement quand leur notification a le droit de passer, avec l’horloge d’un téléphone décalée aussi une fois le relais mis à jour, et jusqu’au bout sur Android 7 et 8 ; un second appel reçoit la réponse occupé, et une sonnerie ne s’arrête que pour son propre appel. Voir [Discuter par un relais](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Appels masqués** : un appel refusé ne laisse plus Erevos par-dessus l’écran de verrouillage, un appel qui arrive pendant que l’écran du mot de passe s’affiche passe par-dessus, et aucun ne sonne deux fois. Voir [Discussions masquées](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Les notifications reviennent aussitôt après un changement de réseau**, et la réception reprend dès qu’Erevos s’affiche quand Android l’avait refusée. Voir [Discuter par un relais](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Les notifications des discussions masquées signalent chaque message une fois** : ce qui est arrivé depuis le dernier regard d’un emplacement est signalé à sa fermeture, un appel qui a sonné n’est plus signalé de nouveau comme message, et un emplacement dont le relais a perdu la file garde son interrupteur activé. Voir [Discussions masquées](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Les discussions masquées se ferment quand Erevos n’est plus affiché**, au bout de 30 secondes, si bien qu’un appel pour elles entre-temps sonne avec leur code PIN pour répondre. Voir [Discussions masquées](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Un message vocal compte une fois**, sur sa dernière partie, même quand il est renvoyé en entier.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Le nombre sur l’icône ne compte que ce qui est encore là** : un message supprimé pour tous, ou lu sur un ordinateur associé, ne compte plus. Voir [Discuter par un relais](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Les messages envoyés pour plus tard** ne se signalent que tant que leur espace est ouvert, sans son s’ils ont été envoyés ainsi.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS** : un SMS pour la discussion à l’écran ne sonne que là, ils ne sont marqués lus que tant que leur écran s’affiche, et Android nomme leurs notifications SMS. Voir [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Rappels** : un rappel vu dans Discussion avec moi-même quitte la notification, ceux d’un emplacement masqué partent avec un nouveau code PIN, et les anniversaires arrivent à 9:00. Voir [Premiers pas](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr lit dès que Tor est prêt.** Voir [Par Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Les notifications d’Erevos montrent son logo** dans la barre d’état.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Les notifications sont demandées même avec la réception désactivée**, quand Signaler les nouveaux messages est activé.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Les photos s’ouvrent sur tout l’écran** : appuie sur une photo pour la voir bord à bord, zoome avec deux doigts ou un double appui, et appuie de nouveau pour cacher ou montrer ce qu’il y a autour ; les grandes photos s’ouvrent comme les petites. Erevos tourne aussi avec le téléphone tant que sa Rotation automatique est activée, et une photo montrée seule même quand elle est désactivée. Voir [Discuter par un relais](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Comptes Matrix dans Erevos** : connecte un espace à Matrix et discute avec des personnes qui utilisent Element ou une autre app Matrix, chiffré de bout en bout, dans Réglages → Relais et réseaux → Matrix. Ces discussions ne sont pas anonymes, et le disent : le serveur Matrix voit qui parle avec qui. Texte, photos et fichiers. Voir [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Les discussions de tous les réseaux sur l’écran d’accueil** : une fois que tu t’es connecté à Matrix, ses discussions sont dans la liste avec les discussions Erevos et les SMS, les plus récentes d’abord, chacune marquée Matrix, et la puce Matrix ne montre qu’elles, comme SMS et Erevos. Voir [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Des versions de test avant une version** : Erevos lit une version comme 4.0.0-rc.1, une version de test qui vient avant la 4.0.0, quand il cherche des mises à jour, annonce une nouvelle version et montre les nouveautés. Voir [Mises à jour](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Vérifier les appareils Matrix par emoji** : dans une discussion avec une personne sur Matrix, Vérifier par emoji vous montre à tous les deux sept images ; si elles correspondent, personne n’est au milieu, et Element voit aussi la vérification. Vérifier cet appareil avec un autre des vôtres fait que votre propre Element fait confiance à Erevos. Voir [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Les sauvegardes automatiques aussi vers ton propre serveur** : sur Android, chaque sauvegarde automatique peut aussi aller dans un dossier sur un serveur de ton choix, comme ton Nextcloud, par WebDAV. Désactivé tant que tu n’en ajoutes pas un. Le serveur reçoit des octets aléatoires sous un nom aléatoire et ne peut pas les ouvrir ; il voit quand même ton compte, ton adresse et quand. Voir [Sauvegardes](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Clé de sécurité et sauvegarde des clés Matrix** : saisissez la clé de sécurité créée par Element, sous Réglages → Relais et réseaux → Matrix, et les messages précédents s’ouvrent, les nouvelles clés sont sauvegardées, et vos autres appareils font confiance à Erevos. Un compte sans clé peut en créer une là. Voir [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix par Tor** : sur Android, le compte Matrix d’un espace suit son choix sous Réglages → Relais et réseaux → Tor, donc le serveur Matrix ne voit plus où tu es ; l’écran Matrix dit quand il passe par Tor. Voir [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Comptes XMPP dans Erevos** : connecte un espace à XMPP, sous Réglages → Relais et réseaux → XMPP, et discute avec des personnes qui utilisent Conversations, Monal, Gajim, Dino ou une autre app XMPP, chiffré avec OMEMO. Ces discussions ne sont pas anonymes, et le disent : le serveur XMPP voit qui parle avec qui. Du texte avec des marques de remise et de lecture, des photos et des fichiers, dans la liste de l’accueil sous une puce XMPP à part, et par Tor sur Android comme tu l’as choisi. Voir [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Appels vocaux et vidéo avec des personnes sur XMPP** : les deux tuiles en haut d’une discussion XMPP appellent la personne, et ses appels sonnent sur le même écran que ceux d’Erevos, avec les apps qui appellent comme Conversations. L’appel passe par ton relais d’appel ou celui du serveur XMPP, donc elle n’apprend pas ton adresse ; la clé qui le prouve passe par les serveurs XMPP, qui pourraient se mettre entre les deux. Voir [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Appels vocaux et vidéo avec des gens sur Matrix** : sur Android, les deux tuiles en haut d’une discussion Matrix appellent avec Element Call, l’app d’appel d’Element et d’Element X, qui s’ouvre dans Erevos dans une fenêtre à elle, et leurs appels sonnent ici comme ceux d’Erevos. Le son et l’image sont chiffrés de bout en bout et passent par le serveur média que ton serveur Matrix indique, jamais par Tor. Voir [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Appels vocaux et vidéo avec des gens sur Matrix, dans l’app web et sur un ordinateur** : les deux tuiles en haut d’une discussion Matrix appellent là aussi avec Element Call, comme sur Android, par-dessus l’app ; la flèche de retour de sa fenêtre la rend petite dans un coin, pour que tu puisses continuer à utiliser Erevos pendant l’appel. Element Call tourne à part d’Erevos et ne peut rien en lire. Voir [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Discussions avec des personnes sur d’autres applis Nostr** : donne à un espace sa propre clé Nostr, dans Réglages → Relais et réseaux → Discussions Nostr, et discute avec des personnes qui utilisent Damus, Amethyst, Primal, 0xchat ou une autre appli Nostr, en tête-à-tête ou en groupe, chiffré comme le demande NIP-17 : les relais voient à qui un message est destiné, pas qui l’a écrit. Ces discussions ne sont pas anonymes, et le disent : ta clé est la même pour tous ceux à qui tu écris. Du texte, des photos, des fichiers et des réactions, dans la liste de l’accueil sous un bouton Nostr à elles, et par Tor sur Android comme tu l’as choisi. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Notifications pour les messages Matrix, XMPP et Nostr** : un message dans une discussion Matrix, XMPP ou Nostr affiche une notification et compte dans le nombre sur l’icône d’Erevos, comme dans les discussions d’Erevos lui-même. Sur Android, Notifications, en bas d’une telle discussion, la met en sourdine ou lui donne un son à elle, et un appel XMPP ou Matrix sonne avec la sonnerie de sa discussion. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Un espace fermé signale les messages Matrix** : sur Android, « Signaler les nouveaux messages » sous « Tant que cet espace est fermé », sur l’écran Matrix, fait dire « Nouveau message » à un espace fermé quand quelque chose arrive sur Matrix pendant qu’un autre espace est ouvert, jamais quoi, de qui ni dans quelle discussion. Désactivé tant que vous ne le choisissez pas. Le serveur Matrix signale alors chaque message au relais de l’espace, sans aucun de ses mots : il apprend l’adresse du relais, et le relais quand des messages arrivent. Voir [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Fait avec l’open source des autres** : Dans À propos d’Erevos et dans le guide, les projets open source sur lesquels Erevos est construit sont désormais nommés, avec leurs auteurs et leurs licences. Voir [Ce qu’est Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Groupes sur XMPP** : sous Réglages → Relais et réseaux → XMPP, crée un groupe privé avec tes contacts, chiffré avec OMEMO pour chaque membre comme les groupes privés de Conversations, ou rejoins un groupe par son adresse, et réponds aux invitations à des groupes. Un groupe qui n’est pas privé, un canal, n’est pas chiffré, et le dit. Tes groupes suivent les autres apps XMPP de ton compte, et un canal ne signale que les messages qui te nomment. Voir [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Davantage dans les discussions Matrix** : appuyez longuement sur un message pour y réagir, lui répondre, le copier et, s’il est de vous, le modifier ou le supprimer pour tout le monde. « Charger les messages précédents » ramène les plus anciens, et le micro sous le champ du message envoie des messages vocaux qu’Element lit aussi. Les réactions ne sont pas chiffrées, comme Element les envoie. Voir [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**La vidéo ajoutée à un appel XMPP** : dans un appel vocal avec quelqu’un sur XMPP, chacun de vous peut activer la vidéo avec « Ajouter la vidéo » ; l’autre personne est d’abord interrogée et peut répondre « Pas maintenant ». Cela marche avec les applis qui ajoutent la vidéo à un appel comme Conversations. Voir [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Messages vocaux et réponses dans les discussions Nostr** : maintenez le micro sous le champ du message pour envoyer un message vocal, qui se lit avec « Lire » ; appuyez longuement sur un message pour lui répondre, et la réponse montre le message auquel elle répond, ici et dans les autres applis Nostr. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 dans les discussions XMPP** : un message à quelqu’un dont l’appli parle OMEMO 2, comme Kaidan, part maintenant avec OMEMO 2 vers cette appli et avec OMEMO 0.3 vers ses autres applis, comme avant. L’écran XMPP montre la clé de cet appareil des deux façons, pour la comparer avec ce que montre chaque appli. Voir [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Les discussions masquées peuvent avoir leurs propres comptes Matrix, XMPP et Nostr** : sous la liste d’un emplacement de discussions masquées, Matrix, XMPP et Nostr ouvrent un compte de cet emplacement seul, à part de celui de l’espace et gardé chiffré avec la clé des discussions masquées. Ses discussions ne s’affichent que parmi les discussions masquées. Il se connecte tant qu’elles sont ouvertes, et aussi quand elles sont fermées si Recevoir une fois fermées est activé, comme le font les discussions masquées elles-mêmes : alors un message dit seulement « Nouveau message », et un appel sonne sans nom et se prend avec le code PIN. Voir [Discussions masquées](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP et Nostr dans les sauvegardes** : une sauvegarde contient désormais les comptes Matrix, XMPP et Nostr de chaque espace et de ses discussions masquées. Après une restauration, une clé Nostr revient avec ses discussions telles qu’elles étaient ; un compte XMPP continue comme un nouvel appareil du compte, avec ses contacts et ses discussions ; un compte Matrix est lâché sur ce téléphone, et l’espace se reconnecte comme un nouvel appareil ; sa clé de sécurité ouvre les messages d’avant. Voir [Sauvegardes](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Les messages vocaux Matrix montrent leur forme d’onde, et les réponses Nostr peuvent être des photos** : un message vocal envoyé dans une discussion Matrix porte sa forme d’onde, qu’Element dessine, et un message vocal qui arrive avec une forme d’onde la montre sous Lire ; dans une discussion Nostr, une photo, un fichier ou un message vocal envoyé pendant qu’un message s’affiche au-dessus du champ lui répond. Voir [Matrix](#matrix) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Appels de groupe dans les groupes XMPP** : dans un groupe privé XMPP, lance un appel vocal ou vidéo, réponds à un appel qui sonne ou rejoins un appel en cours, avec des personnes qui utilisent Dino. Voir [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Un appel vers un téléphone lent sonne en entier** : celui qui appelle attend maintenant jusqu\'à une minute et quart que l\'autre téléphone dise qu\'il sonne, puis 45 secondes à partir de là, si bien qu\'un appel arrivé en retard ne sonne plus pour s\'arrêter aussitôt ; et le téléphone appelé lit un appel avant tout ce qu\'il a à envoyer, et attend de nouveau les appels tout de suite après un changement de réseau. Voir [Discuter par un relais](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**L’app web et l’ordinateur joignent les serveurs Matrix, XMPP et Nostr en HTTPS** : la politique de leur page n’autorisait que les connexions WebSocket, si bien que la connexion à Matrix, la découverte du serveur XMPP et l’envoi de fichiers, ainsi que les fichiers et les recherches de noms sur Nostr, échouaient là. Tout marche maintenant. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Un message envoyé pendant qu’une discussion s’ouvre l’attend**, marqué Envoi…, et part dès qu’elle est ouverte, sans dire qu’Erevos ne peut pas chiffrer.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ce que tu lis pendant qu’une discussion s’ouvre reste lu** : l’écran d’accueil ne le compte plus comme nouveau.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Plus de question de Samsung sur son partage** : sur un téléphone Samsung, Wi-Fi Aware et le Wi-Fi avec les téléphones à proximité restent désactivés tant que tu ne les actives pas. Voir [Discuter avec un téléphone à proximité](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Le champ du SMS garde sa largeur sur un petit écran** : Photo et Envoyer à côté sont des boutons ronds, comme dans une discussion.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Envoyer réagit aussitôt** : une courte vibration à l’appui, le champ se vide et le message apparaît, marqué Envoi…, si bien qu’il ne part jamais deux fois.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**L’écran ne reste plus remonté** après que le clavier s’est fermé derrière un panneau, une boîte de dialogue ou une autre app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importer une discussion avec ses photos ne fige plus Erevos** : l’écran reste vivant pendant l’arrivée des fichiers, dit quelle part en est arrivée, et **Annuler** l’arrête. Une discussion déplacée dans les discussions cachées emporte les discussions importées dedans. Voir [Discussions importées](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Ton relais prouve sa propre clé** : chaque connexion commence par une vérification que seul le relais qui détient cette clé peut réussir, donc personne entre les deux ne peut se faire passer pour lui. Une fois qu’il l’a prouvée, Erevos ne le joint plus jamais sans cette vérification. Ton relais doit être mis à jour pour cela.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparence](#transparency), une nouvelle partie du guide : ce que le serveur derrière Erevos garde et combien de temps, ce qu’il ne garde pas, et qui d’autre voit quelque chose.',
  "**What's new**: this list, in Settings → General, by version.": '**Nouveautés** : cette liste, dans Réglages → Général, par version.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Rien ne se voit derrière le code PIN d’une discussion** : aucun message d’une discussion verrouillée par un code PIN n’est affiché avant que son code PIN soit saisi, et avec le verre, un fond d’écran ou un style qui dessine sa propre scène, l’écran du code PIN est un givre dense qui ne laisse rien voir.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Un appel vidéo de groupe en haut du groupe** : une caméra bleue à côté du combiné vert, comme dans la discussion avec un contact.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Une file du relais pour chaque contact** : chaque contact écrit dans une file que lui seul connaît, si bien que le relais ne peut pas savoir que deux contacts écrivent au même téléphone, et supprimer ou bloquer quelqu’un n’efface que la sienne. Votre relais doit être mis à jour pour cela.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Les discussions masquées, plus comme les autres** : elles se ferment après 30 secondes en arrière-plan, pas tout de suite, et jamais pendant un appel ni pendant que vous choisissez une photo ou un fichier ; ouvertes, un message joue son son, et les aperçus de liens y ont leur propre interrupteur. Voir [Discussions masquées](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Des discussions masquées qui reçoivent une fois fermées** : un interrupteur en haut de chaque emplacement, activé pour les nouveaux, les fait recevoir comme vos autres discussions : leurs contacts voient aussitôt qu’un message est arrivé, une notification dit seulement « Nouveau message », et un appel sonne sans nom. Voir [Discussions masquées](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Les discussions masquées attendent et importent aussi** : ce qui ne peut pas partir maintenant attend, marqué « En attente », et part tout seul par leur relais ; « Envoyer plus tard » y fonctionne comme dans vos autres discussions ; et une discussion de Telegram, WhatsApp ou Viber peut être importée dans une discussion masquée, gardée là seulement. Voir [Discussions masquées](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Les discussions masquées en liste comme vos discussions** : elles s'ouvrent sur une liste comme celle de l'écran d'accueil, avec ce qui a été dit en dernier et combien ne sont pas lus, et chaque emplacement a en haut sa propre Discussion avec moi-même. Voir [Discussions masquées](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Plus dans les discussions masquées** : avec Recevoir une fois fermées, ce qui leur arrive par Nostr est lu aussi pendant qu'elles sont fermées ; et on peut y ajouter un contact depuis une photo de son code QR, et donner une photo à un contact masqué. Voir [Discussions masquées](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Discussions masquées sans relais** : comme vos autres discussions, elles peuvent commencer par Nostr seul : leur lien de contact et leur code QR disent où elles lisent là-bas, et les textes et réactions y vont. Voir [Discussions masquées](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Groupes dans les discussions masquées** : sous leur liste, Nouveau groupe crée un groupe avec leurs contacts ; il figure parmi leurs discussions, passe par leur relais seul, et est lu pendant qu'elles sont fermées si Recevoir une fois fermées est activé. Voir [Discussions masquées](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Plus de ligne « version de test »** : l'écran d'accueil ne se termine plus en disant que c'est une version de test. Le guide dit toujours exactement ce qui est protégé, et que rien n'a encore été audité. Voir [Ce qui est protégé aujourd'hui](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Le menu des contacts dans les discussions masquées** : leurs Contacts ont de nouveau un menu, avec seulement ce qui est à elles : un fichier .vcf importé chez elles, leurs contacts enregistrés en fichier .vcf, et le code QR d’un contact lu sur une photo. Un identifiant Erevos saisi là ajoute la personne aux discussions masquées. Voir [Contacts](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Le bouton d’appel mobile pour plus de contacts** : le clavier orange en haut de la discussion d’un contact prend aussi le numéro du contact auquel tu l’as associé (**Associer à un de mes contacts**), le mobile en premier.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Les discussions Viber s’importent** : depuis le fichier HTML de l’app Android Backup Text for Viber, le texte seulement.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Commencer sans relais, par Nostr** : **Commencer sans relais** dans Nouvelle discussion. Les textes, stickers, réactions, modifications et les marques « arrivé » et « lu » passent par Nostr via Tor. Les photos, messages vocaux, fichiers et appels ont encore besoin d’un relais ou d’un téléphone à proximité.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Le relais vient tout seul** : qui a un relais qui invite envoie une fois une invitation à un contact sans relais, dans la discussion, et l’autre téléphone l’accepte tout seul.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Prévenu quand une nouvelle version sort** (Android) : une fois par jour, Erevos demande au serveur de LPHL, puis affiche une ligne Erevos épinglée et une notification, seulement pour une version signée par l’ordinateur des versions. Cela se désactive dans Réglages → Général → Mises à jour.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Verrouiller une discussion par un code PIN** : Détails → Verrouiller par un code PIN, pour les discussions et les groupes. Rien n’en apparaît dans la recherche, les messages avec étoile ni les importations. Dans les discussions masquées, aucun code PIN n’est demandé.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Un nouveau combiné** sur les tuiles vertes : Téléphone, et l’appel dans une discussion.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Un nouvel écran Nouvelle discussion** : « Comment tu te connectes maintenant » en haut, trois grandes cartes pour un téléphone sans relais (J’ai une invitation, Se connecter avec LPHL, Commencer sans relais), et la partie technique sous « Pour les utilisateurs avancés ».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr plus stable via Tor** : chaque relais Nostr a son propre chemin dans Tor, et après un échec il essaie une nouvelle sortie. Une erreur plus claire sur l’écran Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quand la connexion au relais tombe** pendant qu’Erevos l’attend, Erevos s’en rend compte et se reconnecte, là où il restait bloqué avant.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Inviter par SMS** (Android) : sur la fiche d’un contact du téléphone, pour une personne, pendant 2 jours. Le lien ouvre une page qui propose Erevos (l’APK pour Android, l’app web pour un iPhone ou un ordinateur), puis ouvre l’invitation. Le code QR et « Partager l’invitation » restent comme avant.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Corrections de l’invitation par SMS** : un lien copié sous la forme /i/#… marche aussi, une app web plus ancienne ouvre elle aussi l’invitation, et sous iOS 26 elle indique que Partager est dans •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Un bouton d’appel téléphonique** dans les discussions Erevos et les discussions SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Modifier un message** envoyé, jusqu’à un jour après : pour les contacts, les groupes et les appareils associés, avec « Modifié » à côté de l’heure.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr dit ce qu’il a fait** : « Envoyé par Nostr », et sur l’écran Nostr ce que chaque relais a fait en dernier.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Des boutons d’appel en couleur** en haut d’une discussion : vidéo en bleu, voix en vert.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Des flèches vers le début et la fin d’une discussion ; les messages plus anciens arrivent tout seuls quand tu fais défiler.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Les discussions importées de Telegram et WhatsApp ressemblent aux messages Erevos : bulles, jours, photos, messages vocaux, recherche.',
  'Dogs instead of cats in the stickers.': 'Des chiens au lieu des chats dans les stickers.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Captures d’écran : un interrupteur dans Réglages → Confidentialité et sécurité.',
  'Hidden chats from New chat: hold it for a second.': 'Les discussions masquées depuis Nouvelle discussion : reste appuyé une seconde dessus.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Des tuiles en couleur sur l’écran d’accueil : Téléphone en vert, Contacts en violet, le cadenas en orange.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Discussion avec moi-même**, toujours en premier, et **Me rappeler**, la cloche orange.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Médias, liens et fichiers** dans les Détails d’une discussion, avec un calendrier et « Aller à un jour ».',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importer une discussion depuis la discussion elle-même : Détails → Discussions importées.',
  'A closed space can say that a message came while another space is open.': 'Un espace fermé peut signaler qu’un message est arrivé pendant qu’un autre espace est ouvert.',
  'The message menu says when a message went or came through Nostr.': 'Le menu d’un message indique s’il est parti ou arrivé par Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Soutenir Erevos** : Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Qui fait Erevos et pourquoi, dans À propos d’Erevos ; le guide dit partout pourquoi.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Les réglages en 8 groupes**, avec une recherche : Général, Apparence, Notifications, Confidentialité et sécurité, Relais et réseaux, Téléphone et SMS, Données et appareils, Pour les tests. Le ⋯ de l’écran d’accueil ne garde que les écrans, et Réglages en dernier.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Rechercher des mises à jour dit ce qui a bloqué une mise à jour.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    '« Inviter quelqu’un » ne passe plus par un jeton commun ; il te demande d’abord de te connecter au relais.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Le jeton commun du relais devient tout seul un jeton propre au téléphone (le relais doit être à jour).',
  'A relay that refuses through Tor says why.': 'Un relais qui refuse par Tor dit pourquoi.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Moins de batterie en arrière-plan : le relais, Tor et les radios de proximité.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos ne se ferme plus quand tu fais un sticker à partir d’une photo.',
  'Hidden chats’ notices are right.': 'Les notifications des discussions masquées sont justes.',
  'Hidden chats by holding New chat.': 'Les discussions masquées en restant appuyé sur Nouvelle discussion.',
  'A search for contacts on the Phone.': 'Une recherche de contacts dans Téléphone.',
  'New chat shows first how to add a contact.': 'Nouvelle discussion montre d’abord comment ajouter un contact.',
  'A call shows over the screen saver, and the screen wakes.': 'Un appel s’affiche par-dessus l’économiseur d’écran, et l’écran se réveille.',
  'Erevos in other apps’ Share.': 'Erevos dans le menu Partager des autres apps.',
  'A sound for every new message, also while Erevos shows.': 'Un son pour chaque nouveau message, même quand Erevos est à l’écran.',
  'The SMS settings say right what holding does.': 'Les réglages SMS disent correctement ce que fait un appui long.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Chaque icône ouvre ce qu’elle indique : Erevos, SMS, Téléphone, Contacts, le widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Les messages par Tor par défaut** : Messages, Tout ou Rien.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Les textes par Nostr** : trois relais publics, par Tor, avec ton propre relais en secours après 5 minutes.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Une seule invitation pour tout : le relais et le contact ensemble.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Des règles anti-spam pour les expéditeurs et les numéros de l’étranger, avec la raison.',
  '480 stickers in 20 sets.': '480 stickers en 20 séries.',
  'Lighter chats on older phones; QR codes at once.': 'Des discussions plus légères sur les anciens téléphones ; les codes QR tout de suite.',
  'Copy code for one-time codes in SMS.': '« Copier le code » pour les codes à usage unique dans les SMS.',
  'Locked, Erevos keeps receiving.': 'Verrouillé, Erevos continue de recevoir.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Des contacts plus rapides ; la notification des discussions masquées ne compte que les messages.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Le relais essaie chaque adresse : push, autres relais, la connexion LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Glisser sur les onglets ne fait que changer d’onglet.',
  'The icons fill the launcher’s shape.': 'Les icônes remplissent la forme du lanceur.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Des icônes en couleur (Erevos en rouge, Téléphone en vert, SMS en bleu, Contacts en violet) et une nouvelle icône SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Une couleur pour chaque icône, et l’ordre des boutons du widget.',
  'Swipe to go back, and between tabs.': 'Glisser pour revenir en arrière, et entre les onglets.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Une mise à jour de la WebView ne ferme plus Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Supprimer ou bloquer un contact te donne une nouvelle file d’attente sur le relais.',
  'A new contact can take the name of a contact on the phone.': 'Un nouveau contact peut prendre le nom d’un contact du téléphone.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Se connecter au relais avec LPHL**, et **les invitations au relais**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Des autorisations dans l’app web, et davantage sur Android ; la notification de l’app web dit combien de messages sont arrivés.',
  'Hidden chats can ring calls while they are closed.': 'Les discussions masquées peuvent faire sonner les appels quand elles sont fermées.',
  'New keys every month in chats, every week in groups.': 'De nouvelles clés chaque mois dans les discussions, chaque semaine dans les groupes.',
  'Linked devices work with the phone off.': 'Les appareils associés fonctionnent téléphone éteint.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Un nouvel écran de discussion ; les codes QR depuis une photo ; Téléphone pour les petits écrans.',
  'Add as contact inside a group.': '« Ajouter comme contact » dans un groupe.',
  'Stickers in sets, moving, and your own.': 'Des stickers en séries, animés, et les tiens.',
  'SMS inside the Erevos chat.': 'Les SMS dans la discussion Erevos.',
  'Android updates need the release computer’s signature.': 'Les mises à jour Android exigent la signature de l’ordinateur des versions.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Une version F-Droid ; le serbo-croate ; de nouveaux numéros de version.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Beaucoup pour la sécurité : Argon2id, des messages chiffrés aussi pour le relais, un jeton pour chaque téléphone, aucun lien ne lance d’appel.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Les importations depuis Telegram et WhatsApp apportent photos, vidéos, messages vocaux et fichiers.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Un téléphone sans relais communique par une place sur le relais d’un contact.',
  // 0.1.14
  'Back to my chats, for hidden chats.': '« Retour à mes discussions », pour les discussions masquées.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos reçoit et sonne même une fois balayé hors des applis récentes.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Les discussions masquées peuvent signaler qu’un message est arrivé.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Corrections : menus, codes QR depuis une photo, Bluetooth sous Android 17, longues listes.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Téléphone sans le mot de passe, si tu l’autorises ; un widget pour l’écran d’accueil ; un filtre SMS et Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Les liens attendent le mot de passe ; les icônes Téléphone et Contacts ; l’ID Erevos sur un contact.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 nouvelles fonctions : 5 nouvelles langues, appareils associés, groupes publics, réponses, réactions, sondages, envoi différé, Erevos comme app de téléphone et de contacts, ponts Tor, l’empreinte digitale, Windows et plus encore.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Les notifications SMS en arrière-plan.',
  'The web app comes out with every release.': 'L’app web sort avec chaque version.',
  'Greek in the whole app.': 'Le grec dans toute l’app.',
  'Web Push in the web app.': 'Web Push dans l’app web.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'La première version Android signée : discussions chiffrées, appels, groupes, discussions masquées, sauvegardes, importations, et téléphones à proximité sans internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Deux nouvelles séries d'autocollants de 24 humeurs** : **Tux**, le manchot de Linux tel qu'il est dessiné, et **Aïkido**, un aïkidoka en keikogi et large hakama, qui salue aussi, s'assoit en seiza et fait une roulade.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Une nouvelle série d'autocollants, Takis** : une caricature en costume sombre et cravate violette à pois, en 24 humeurs qui bougent.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Photos, fichiers et messages vocaux sans relais** : quand il n’y a pas de relais entre toi et ton contact et qu’il lit sur Nostr, un message vocal passe par Nostr comme un texte, une photo jusqu’à 3 Mo en morceaux, et une photo plus grande, une vidéo ou un autre fichier, jusqu’à 20 Mo, vers un serveur de fichiers chiffré (Blossom), le tout via Tor. Voir [Par Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Plus de batterie économisée en arrière-plan, si tu le choisis** : dans Réglages → Notifications → En arrière-plan, Seulement le gaspillage reste le choix par défaut ; Et les téléphones proches éteint aussi les radios pour téléphones proches tant qu’Erevos est en arrière-plan ; Et le sommeil laisse aussi dormir le téléphone, si bien qu’Erevos regarde ton relais environ une fois par minute et qu’un message ou un appel peut avoir une ou deux minutes de retard. Android seulement. Voir [Discuter par un relais](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Un contact supprimé ne revient plus d’une ancienne demande** : dans un groupe, un membre dont tu avais demandé le lien de contact, ou qui avait demandé le tien, et que tu supprimais ensuite comme contact avant qu’Erevos regarde de nouveau le relais, pouvait être ajouté de nouveau par cette ancienne demande. La suppression la lâche maintenant aussitôt. Voir [Discussions de groupe](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Chaque message dit par où il est passé** : appuie longuement sur un message et son menu dit s’il est parti ou arrivé par le relais, par Nostr, par un téléphone proche ou par LoRa. Les messages d’avant ne disent rien. Voir [Par Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Le filtre de spam lit les mots comme ils se voient** : un SMS d’arnaque qui remplace une lettre par une autre, semblable, d’un autre alphabet, ou cache dans un mot une marque qu’on ne voit pas, ne le trompe plus. Voir [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Médias, liens et fichiers aussi dans les groupes** : dans les détails d’un groupe, une liste de ses photos, vidéos, messages vocaux, musiques, fichiers et liens, chaque sorte à part sous ses mois, avec un calendrier, comme dans la discussion d’un contact. Un appui ouvre ou lit ; maintenu, chacun mène à son message. Voir [Discussions de groupe](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Un redémarrage du relais n’apporte plus de fausse notification** : après le redémarrage de ton relais, une discussion masquée ou un espace fermé disait de nouveau Nouveau message pour des messages qu’il avait déjà signalés. Ton relais doit être mis à jour pour cela. Voir [Discussions masquées](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Des sauvegardes vers ton serveur par Tor** : sur Android, les sauvegardes automatiques envoyées à ton propre serveur suivent maintenant le choix de l’espace sous Réglages → Relais et réseaux → Tor, comme Matrix, donc avec Tor le serveur ne voit plus où tu es. Aussi vers un serveur dit quand elles passent par Tor. Voir [Sauvegardes](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Restaurer une sauvegarde directement depuis ton serveur** : Restaurer depuis un serveur, dans Sauvegardes, montre les sauvegardes de ton serveur, les plus récentes d’abord, et ouvre celle que tu choisis avec son mot de passe, sans téléchargement à la main, sur un nouveau téléphone aussi. Voir [Sauvegardes](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Des sauvegardes vers ton serveur depuis un ordinateur et l’app web aussi** : dans l’app de bureau, les sauvegardes automatiques vont vers ton serveur WebDAV comme sur Android ; dans l’app web, Envoyer une sauvegarde maintenant en envoie une là-bas, avec un serveur qui laisse entrer l’app web. Les deux peuvent restaurer depuis lui. Pas par Tor. Voir [Sauvegardes](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Vérifier un contact en personne avec des codes QR** : sous Numéro de sécurité, dans les détails d’une discussion, chaque téléphone montre un code ; photographiez le code de l’autre téléphone, et lui le vôtre. Quand ça correspond, le contact est marqué Vérifié en personne. Rien n’est envoyé. Voir [Discuter par un relais](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Jusqu’à trois relais d’attache** : sous Réglages → Relais et réseaux → Relais d’attache, Ajouter un autre relais d’attache donne à un espace jusqu’à deux de plus, chacun avec sa propre file. Votre lien de contact et vos messages les nomment dans l’ordre, et vos contacts essaient chacun tant que les précédents sont injoignables. Voir [Relais d’attache](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Présentez deux de vos contacts** : dans les détails de la discussion d’un contact, Présenter à un contact le sollicite, ainsi qu’un autre de vos contacts, chacun dans votre discussion avec lui. Ils ne deviennent contacts que si les deux disent oui, et aucun ne sait si l’autre a dit non. Voir [Discuter par un relais](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Un Bluetooth qu’on ne peut pas suivre** : le nombre aléatoire que votre téléphone émet en Bluetooth pour que les téléphones proches le trouvent ne changeait qu’au redémarrage d’Erevos ; il change maintenant toutes les neuf à douze minutes, si bien que personne à l’écoute ne peut suivre votre téléphone d’un endroit à l’autre grâce à lui. Les téléphones avec un Erevos plus ancien trouvent toujours le vôtre. Voir [Discuter avec un téléphone à proximité](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Les discussions masquées s’affichent aussitôt** : dès que le code PIN les ouvre, leurs discussions et leurs contacts s’affichent aussitôt, pour les lire, pendant que prend fin ce qu’elles recevaient en arrière-plan ; avant, cela pouvait les retenir longtemps, car cette réception peut passer par Tor. Voir [Discussions masquées](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**Le mot de passe de vos sauvegardes en morceaux chez des amis** : dans Réglages → Données et appareils → Morceaux de sauvegarde, donnez-en des morceaux à 3 à 5 contacts ; 2 ou 3 d’entre eux, n’importe lesquels, le redonnent, un seul ne montre rien. Chacun passe dans le chiffrement de votre conversation avec eux et seul leur Erevos le garde ; votre téléphone n’en garde aucun. Voir [Morceaux de sauvegarde chez des amis](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Bouton de panique** : dans Réglages → Confidentialité et sécurité → Bouton de panique, effacez d’un toucher tout ce qu’Erevos garde ici, sur Android et dans l’app web. Sur Android, une app de panique comme Ripple peut aussi le faire, mais seulement celle à laquelle vous dites oui, vérifiée par sa signature. Voir [Bouton de panique](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos vers un téléphone proche, sans internet** : dans Réglages → Général → Donner Erevos à un téléphone proche, ce téléphone sert son Erevos sur le même Wi-Fi ou son point d’accès pendant dix minutes, avec un code QR. Un téléphone sans Erevos le télécharge dans le navigateur ; un téléphone avec un Erevos plus ancien le prend dans Mises à jour → Depuis un téléphone proche, qui ne l’installe que si c’est Erevos, signé comme celui-là. Voir [Erevos vers un téléphone proche](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Discussions masquées avec les téléphones à proximité**: tant que les discussions masquées sont ouvertes, ou reçoivent fermées, elles atteignent le téléphone d’un contact à proximité par Bluetooth, Wi-Fi Aware, Wi-Fi Direct ou sur le même Wi-Fi, sans internet, comme vos autres discussions. L’espace n’apprend jamais qu’un contact masqué est à proximité, et rien dans l’air ne distingue leurs messages de ceux de l’espace ; d’autres téléphones ne les portent jamais, et elles ne passent jamais par LoRa ni par SMS. Voir [Discussions masquées](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**Le même Wi-Fi sur Sailfish OS**: Erevos sur Sailfish OS trouve les téléphones et ordinateurs avec Erevos sur le même Wi-Fi ou le partage de connexion d’un téléphone et leur parle sans internet, comme sur un ordinateur. Voir [Sur Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Les téléchargements s’arrêtent à 100 Mo** : un fichier, une sauvegarde depuis un serveur ou tout autre téléchargement est lu à mesure qu’il arrive et arrêté dès qu’il dépasse 100 Mo, ou moins là où les fichiers du réseau sont plus petits, comme 20 Mo pour les fichiers Nostr, si bien qu’un serveur de fichiers qu’un contact désigne ne peut plus remplir la mémoire du téléphone d’une réponse sans fin. Une sauvegarde sur un serveur revient jusqu’à 100 Mo ; téléchargez-en une plus grande et ouvrez-la avec Restaurer une sauvegarde. Voir [Sauvegardes](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Photos de profil sur Matrix et XMPP** : les contacts et les salons Matrix montrent leur photo dans la liste des discussions, et tu peux mettre la tienne sur les écrans Matrix et XMPP (Choisir une photo). Les photos ne sont chiffrées sur aucun des deux réseaux : le serveur les voit. Voir [Matrix](#matrix) et [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gérer un groupe XMPP** : les admins d’un groupe mettent son sujet et retirent ou bannissent des gens, le propriétaire le renomme et nomme des admins, et dans un canal l’admin voit qui s’y trouve et peut le mettre dehors. Voir [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Vérifier un appareil Matrix par QR code** : une fois la vérification acceptée des deux côtés, Erevos montre un code qu’Element (ou un autre Erevos) photographie, ou photographie le leur, comme Element ; comparer des emoji reste à un toucher. Voir [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Se connecter à Matrix par authentification unique** (Android) : quand ton serveur Matrix connecte les gens sur sa propre page, comme matrix.org, « Se connecter par authentification unique (SSO) » l’ouvre dans le navigateur et revient à Erevos. Voir [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Un espace fermé signale les messages XMPP** : sur Android, « Signaler les nouveaux messages » sous « Tant que cet espace est fermé », sur l’écran XMPP, laisse un espace fermé dire « New message » quand quelque chose arrive sur XMPP pendant qu’un autre espace est ouvert, jamais quoi, de qui ni dans quelle discussion. Désactivé tant que vous ne le choisissez pas. Il faut un relais mis à jour pour cela et un serveur XMPP qui envoie des notifications aux applis inactives ; le serveur XMPP apprend alors le nom du relais, et le relais quand des messages arrivent. Voir [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Associer un ordinateur est plus clair** : sur un ordinateur, Réglages → Données et appareils → Appareils associés commence désormais par « Associer à mon téléphone », avec le relais de LPHL déjà rempli et « Se connecter avec LPHL » sous le jeton, si bien qu’aucun jeton n’a à être copié depuis le téléphone ; et il dit que le code QR s’affiche dès qu’on touche « Associer à mon téléphone ». Voir [Appareils associés](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Me supprimer partout** : Réglages → Confidentialité et sécurité → Me supprimer partout supprime ce que les serveurs gardent pour l'espace ouvert (ses files sur les relais avec les messages dedans, ce qu'un relais garde pour l'envoyer plus tard, les fichiers qui y attendent, les invitations que personne n'a utilisées), demande via Tor aux relais Nostr d'oublier les clés sur lesquelles vos conversations lisent, et arrête l'espace jusqu'à ce que vous touchiez Relancer. Votre téléphone garde tout. Vous pouvez aussi vous déconnecter de Matrix et XMPP et supprimer le compte Nostr créé ici. Voir [Me supprimer partout](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Toutes les files de relais sur une liste** : les files qu'un espace garde sur les relais sont réunies à un seul endroit, et les vérifications échouent si un nouveau type de file est créé sans y être ajouté, pour que Me supprimer partout n'en laisse aucune.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP et Nostr sur un ordinateur associé** : associer un ordinateur peut aussi y amener les comptes Matrix et XMPP de cet espace et la clé de ses discussions Nostr, chacun connecté là-bas comme un nouvel appareil à lui ; pour un ordinateur déjà associé, touche « Envoyer les comptes » sous lui, sur le téléphone. Un serveur Matrix laisse rarement le téléphone connecter l’ordinateur : l’ordinateur demande alors une fois le mot de passe Matrix, et les clés du compte viennent du téléphone, donc ni clé de sécurité ni vérification par emoji ne sont nécessaires. Voir [Appareils associés](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Seulement les SMS** : quand Erevos est verrouillé, l’icône SMS, le bouton SMS du widget et la notification d’un nouveau SMS demandent le mot de passe, puis n’ouvrent que les SMS. Tout le reste, y compris le cadenas orange **Tout déverrouiller**, le redemande, puis ouvre tout Erevos. Voir [Verrou par mot de passe](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les discussions Nostr avec une clé venue d’une autre appli retrouvent leurs messages** : Erevos lit là où cette appli a dit que tes messages arrivent, comme le fait cette appli, au lieu de ses trois relais propres, récupère les messages gardés là et dans les anciennes listes de la clé, et relit un relais quand il cesse d’envoyer. Avant, une telle clé pouvait montrer ses discussions sans messages passés et n’en recevoir aucun de nouveau. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Les sauvegardes gardent ce dont les discussions fermées ont besoin** : une sauvegarde garde maintenant aussi ce qui permet aux discussions masquées de faire sonner un appel et de prévenir qu’un message est arrivé pendant qu’elles sont fermées, et à un espace fermé de prévenir qu’un message est arrivé. Ainsi, après une restauration, sur un autre téléphone aussi, **Faire sonner les appels quand elles sont fermées**, **Prévenir quand un message arrive** et **Aussi quand un autre espace est ouvert** continuent comme avant. Voir [Sauvegardes](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Ouvrir un autre espace depuis la recherche** : tape le mot de passe d’un autre espace dans **Rechercher dans les discussions** de l’écran d’accueil et appuie sur Entrée : l’espace ouvert se ferme, sans que rien n’en reste, et l’autre s’ouvre, comme avec **Verrouiller maintenant** et son mot de passe. Cela prend le même temps quoi que tu tapes, et un mauvais mot de passe, ou celui de l’espace ouvert, n’est qu’une recherche. Voir [Second mot de passe](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Un point pour les non-lus ailleurs, si tu le veux** : les discussions masquées avec **Recevoir une fois fermées** peuvent afficher un petit point sur la loupe de **Rechercher dans les discussions** tant qu’elles ont un message non lu (leur interrupteur **Point pour les non-lus**), et un espace qui signale qu’un message est arrivé pendant qu’un autre est ouvert peut en afficher un sur le cadenas au-dessus des discussions des autres espaces (**Point dans les autres espaces**). Jamais combien, ni où ; éteint sauf si tu l’allumes. Voir [Discussions masquées](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Pour entrer, l’invitation suffit** : sur un téléphone qui n’a pas encore de relais, **Nouvelle discussion** affiche une façon d’entrer, **J’ai une invitation**. La connexion avec LPHL, **Commencer sans relais** et les réglages du relais sont dans **Pour les utilisateurs avancés**, pour qui les cherche. Et une invitation à ton relais ne donne au relais qu’un nom de lettres et de chiffres au hasard pour le téléphone qu’elle laisse entrer : le nom que tu tapes reste sur ton téléphone, où ta liste d’invitations le montre. Voir [Discuter par un relais](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Les téléphones invités restent** : sur un relais de cette version, un téléphone que tu as invité garde son accès même quand le tien disparaît, et de même les téléphones qu’il a invités ; reprendre une invitation coupe ce seul téléphone. Voir [Discuter par un relais](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Les sauvegardes ramènent le téléphone tel qu’il était** : une sauvegarde contient maintenant aussi les photos, les fichiers et les messages vocaux, dans des fichiers à part à côté d’elle, chacun scellé et lié à sa sauvegarde ; et le mot de passe de panique, les réglages qui te suivent, les réponses rapides du Téléphone et les appels qu’il refuse, les SMS pour plus tard et les sauvegardes automatiques avec leur serveur, mais pas leur dossier. Un SMS pour plus tard dont l’heure est passée avant la restauration attend que tu l’envoies ou le supprimes. Ce qui reste propre à chaque téléphone, comme l’empreinte, les dossiers et ce qu’Android permet, ne revient jamais : après une restauration, les autorisations d’Android s’ouvrent pour les modules activés. Voir [Sauvegardes](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Une sauvegarde plus récente demande un Erevos plus récent** : une sauvegarde faite par un Erevos plus récent que le tien est refusée, sans rien changer, et Erevos te demande de le mettre d’abord à jour vers la dernière version. Un Erevos d’avant la 6.0.0 n’ouvre pas les sauvegardes de la 6.0.0 ou plus récentes : mets-le à jour, puis restaure. Voir [Sauvegardes](#backup).",
};
